int shortestPath(Map<String, List<Edge>> graph, String start, String target) {
  Map<String, Integer> dist = new HashMap<>();
  PriorityQueue<Object[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> (Integer) a[0]));
  dist.put(start, 0); heap.add(new Object[] { 0, start });
  while (!heap.isEmpty()) {
    Object[] item = heap.remove(); int cost = (Integer) item[0]; String node = (String) item[1];
    if (node.equals(target)) return cost;
    if (cost != dist.get(node)) continue;
    for (Edge edge : graph.getOrDefault(node, List.of())) {
      int nextCost = cost + edge.weight;
      if (nextCost < dist.getOrDefault(edge.to, Integer.MAX_VALUE)) { dist.put(edge.to, nextCost); heap.add(new Object[] { nextCost, edge.to }); }
    }
  }
  return -1;
}

