int minRoomsSweep(int[][] intervals) {
  int[] starts = Arrays.stream(intervals).mapToInt(a -> a[0]).sorted().toArray();
  int[] ends = Arrays.stream(intervals).mapToInt(a -> a[1]).sorted().toArray();
