export function countRegionsUnion(grid: number[][]): number {
  const parent = new Map<string, string>();
  const find = (x: string): string => { if (!parent.has(x)) parent.set(x, x); if (parent.get(x) !== x) parent.set(x, find(parent.get(x)!)); return parent.get(x)!; };
  const union = (a: string, b: string) => parent.set(find(a), find(b));
  for (let r = 0; r < grid.length; r += 1) for (let c = 0; c < grid[0].length; c += 1) if (grid[r][c] === 1) {
    const key = r + ',' + c; find(key);
    if (r + 1 < grid.length && grid[r + 1][c] === 1) union(key, (r + 1) + ',' + c);
    if (c + 1 < grid[0].length && grid[r][c + 1] === 1) union(key, r + ',' + (c + 1));
  }
  return new Set([...parent.keys()].map(find)).size;
}

