int countRegionsUnion(int[][] grid) {
  Map<String, String> parent = new HashMap<>();
  for (int r = 0; r < grid.length; r++) for (int c = 0; c < grid[0].length; c++) if (grid[r][c] == 1) {
    String key = r + "," + c; find(parent, key);
    if (r + 1 < grid.length && grid[r + 1][c] == 1) union(parent, key, (r + 1) + "," + c);
    if (c + 1 < grid[0].length && grid[r][c + 1] == 1) union(parent, key, r + "," + (c + 1));
  }
  return (int) parent.keySet().stream().map(k -> find(parent, k)).distinct().count();
}
String find(Map<String, String> parent, String x) { parent.putIfAbsent(x, x); if (!parent.get(x).equals(x)) parent.put(x, find(parent, parent.get(x))); return parent.get(x); }
void union(Map<String, String> parent, String a, String b) { parent.put(find(parent, a), find(parent, b)); }
